window.AUTH=window.AUTH||{};window.AUTH["22-915"]={"d":"22-915","id":"2023/22-915","n":"United States v. Rahimi","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2023-08-14","url":"https://www.supremecourt.gov/DocketPDF/22/22-915/275295/20230814194714856_22-915%20U.S.%20v.%20Rahimi.pdf","side":"pet","n":52},{"k":"united-states","label":"Brief amicus curiae of United States Conference of Catholic Bishops","date":"2023-08-21","url":"https://www.supremecourt.gov/DocketPDF/22/22-915/275890/20230821182527118_22-915%20tsacUSCCB.pdf","side":"us","n":11},{"k":"respondent","label":"Brief of respondent Zackey Rahimi","date":"2023-09-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-915/280662/20230927174948653_Rahimi%20-%2022-915%20-%20Respondent%20Brief%20-%20FINAL.pdf","side":"res","n":69},{"k":"reply","label":"Reply of petitioner United States","date":"2023-10-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-915/286059/20231025143939624_22-915%20USA%20v.%20Rahimi%20reply.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r43_p860.pdf","tr":true,"items":[{"t":"case","label":"Abbott v. Abbott","cite":"67 Me. 304","y":1877,"url":"https://www.courtlistener.com/c/Me./67/304/","by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"better to draw the curtain, shut out the public gaze, and leave the parties to forget and forgive.","cite":"67 Me. 304, 307"}]},{"t":"case","label":"Chouk v. Chouk","cite":"2023 WL 2193405","y":2023,"court":"Ky. Ct. App. Feb. 24","by":{"0":"35"}},{"t":"case","label":"Clementz-McBeth v. Craft","cite":"2012 WL 776851","y":2012,"court":"Ohio Ct. App. Mar. 12","by":{"0":"35"}},{"t":"case","label":"Counterman v. Colorado","cite":"143 S. Ct. 2106","y":2023,"id":"2022/22-138","sc":1,"by":{"0":"37"}},{"t":"case","label":"Dickerson v. New Banner Institute, Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"firearms must be kept away from persons * * * who might be expected to misuse them.","cite":"460 U.S. 103, 119"}]},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"by":{"0":"6, 10-13, 16-18, 36-39, 43","1":"12, 17","2":"1, 9–11, 19, 22, 28, 31–35, 37–39, 41, 44, 49","3":"2-4, 6-10, 13, 17, 18, 20"},"q":[{"src":"brief","b":0,"text":"the right secured by the Second Amendment is not unlimited.","cite":"554 U.S. 570, 626"},{"src":"brief","b":0,"text":"typically possessed by law-abiding citizens for lawful purposes.","cite":"554 U.S. at 625"},{"src":"brief","b":1,"text":"not unlimited, just as the First Amendment’s right of free speech [is] not.","cite":"554 U.S. 570, 595"},{"src":"brief","b":1,"text":"right of law-abiding, responsible citizens to use arms in defense of hearth and home.","cite":"554 U.S. at 635"},{"src":"brief","b":2,"text":"is exercised individually and belongs to all Americans.","cite":"554 U.S. at 581"},{"src":"brief","b":2,"text":"a small fine and forfeiture of the weapon (or in a few cases a very brief stay in the local jail).","cite":"554 U.S. at 633"},{"src":"brief","b":3,"text":"a variety of legal and other sources","cite":"554 U.S. at 605"},{"src":"brief","b":3,"text":"has long been understood to be the predecessor to our Second Amendment.","cite":"554 U.S. at 593"},{"src":"argument","who":"Mr. Wright","text":"Setting aside an enumerated powers problem, so they're in the District of Columbia or something like that, there's definitely a tradition for restricting sale or provision of weapons to the mentally ill that -- the -- all the -- all the -- all the examples that the government has cited are late."}]},{"t":"case","label":"Duckworth v. Arkansas","cite":"314 U.S. 390","y":1941,"id":"scdb/1941-027","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"sluggishness of government, the multitude of matters that clamor for attention, and the relative ease with which men are persuaded to postpone troublesome decisions.","cite":"314 U.S. 390, 400"}]},{"t":"case","label":"Kanter v. Barr","cite":"919 F.3d 437","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/919/437/","by":{"0":"28","1":"15, 17, 20, 22","2":"32, 34, 35"},"q":[{"src":"brief","b":0,"text":"who have demonstrated a proclivity for violence or whose possession of guns would otherwise threaten the public safety,","cite":"919 F.3d 437, 454"},{"src":"brief","b":1,"text":"‘indicate some common if imprecise understanding at the Founding regarding the boundaries of a right to keep and bear arms.’","cite":"919 F.3d 437, 455"},{"src":"brief","b":1,"text":"founding-era legislatures categorically disarmed groups whom they judged to be a threat to the public safety.","cite":"919 F.3d at 458"}]},{"t":"case","label":"McDonald v. City of Chicago","cite":"561 U.S. 742","y":2010,"id":"2009/08-1521","sc":1,"by":{"0":"8, 10, 11, 35","2":"9, 10, 21, 30, 31, 38, 39, 41, 44","3":"2, 19"},"q":[{"src":"brief","b":2,"text":"the need for defense of self, family, and property is most acute[.]","cite":"561 U.S. at 767"},{"src":"brief","b":2,"text":"bans comparable to those at issue here and in Heller.","cite":"561 U.S. at 786"},{"src":"opinion","who":"Justice Kavanaugh, concurring","text":"think the States may be on to something, we can loosen the leash.","cite":"561 U. S. 742, 803"},{"src":"opinion","who":"Justice Kavanaugh, concurring","text":"the question to be decided is not whether the historically focused method Page Proof Pending Publication is a perfect means of restraining aristocratic judicial Constitution-writing; but whether it is the best means available in an imperfect world.","cite":"561 U. S., at 804"},{"src":"opinion","who":"Justice Jackson, concurring","text":"[M]any of the over 180,000 African-Americans who served in the Union Army returned to the States of the old Confederacy, where systematic efforts were made to disarm them and other blacks.","cite":"561 U. S. 742, 771"},{"src":"argument","who":"General Prelogar","text":"Like Heller and McDonald, Bruen recognized that Congress may disarm those who are not law-abiding, responsible citizens. That principle is firmly grounded in the Second Amendment's history and tradition."},{"src":"argument","who":"General Prelogar","text":"And the reason that we've used the term \"not responsible\" is it -- it's because it's the own -- the standard that this Court itself has articulated in Heller and repeated in McDonald and then repeated again in Bruen."},{"src":"argument","who":"General Prelogar","text":"And I think it would be important, if the Court wants to refer to concepts of dangerousness, to make clear that it's not backtracking from what it said in Heller and in McDonald and in Bruen, that you can disarm those who are not law-abiding, responsible citizens, with the mentally ill as one of the exemplar categories the Court held up to illustrate that proposition."}]},{"t":"case","label":"McIntyre v. Ohio Elections Commission","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"by":{"0":"39"},"q":[{"src":"opinion","who":"Justice Kavanaugh, concurring","text":"Where the meaning of a constitutional text (such as `the freedom of speech') is unclear, the widespread and longaccepted practices of the American people are the best indication of what fundamental beliefs it was intended to enshrine.","cite":"514 U. S. 334, 378"}]},{"t":"case","label":"NYSRPA v. Bruen","cite":"142 S. Ct. 2111","y":2022,"id":"2021/20-843","sc":1,"by":{"0":"5, 6, 10-13, 15, 22, 24, 35-39, 41, 42, 46","1":"1, 3, 14, 16, 23, 25","2":"1, 7, 8, 11, 12, 14, 17, 18, 20, 24, 27–33, 37, 39, 41, 42, 44","3":"1-7, 10, 12-14, 20, 21"},"q":[{"src":"brief","b":0,"text":"the right of an ordinary, law-abiding citizen to possess a handgun in the home.","cite":"142 S. Ct. at 2122"},{"src":"brief","b":0,"text":"how and why the regulations burden a law-abiding citizen’s right to armed self-defense.","cite":"142 S. Ct. at 2133"},{"src":"brief","b":1,"text":"‘the right of law abiding, responsible citizens to use arms’ for self-defense.","cite":"142 S. Ct. at 2131"},{"src":"brief","b":1,"text":"typically targeted only those threatening to do harm.","cite":"142 S. Ct. at 2148"},{"src":"brief","b":2,"text":"the Constitution presumptively protects that conduct.","cite":"142 S. Ct. at 2129"},{"src":"brief","b":2,"text":"is consistent with this Nation’s historical tradition of firearm regulation.","cite":"142 S. Ct. at 2126"},{"src":"brief","b":3,"text":"ordinary, law-abiding citizens have a similar right to carry handguns publicly","cite":"142 S. Ct. at 2122"},{"src":"brief","b":3,"text":"to determine the public understanding of","cite":"142 S. Ct. at 2136"}]},{"t":"case","label":"NYSRPA v. City of New York","cite":"140 S. Ct. 1525","y":2020,"id":"2019/18-280","sc":1,"by":{"0":"28"}},{"t":"case","label":"Parke v. Raley","cite":"506 U.S. 20","y":1992,"id":"1992/91-719","sc":1,"by":{"0":"44","3":"16"}},{"t":"case","label":"Patterson v. Winn","cite":"5 Pet. 233","y":1831,"url":"https://www.courtlistener.com/c/Pet./5/233/","by":{"0":"23"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"probably does more to combat gun violence than any other federal law.","cite":"139 S. Ct. 2191, 2201"}]},{"t":"case","label":"Robertson v. Baldwin","cite":"165 U.S. 275","y":1897,"id":"scdb/1896-088","sc":1,"by":{"0":"36","1":"16","2":"33"},"q":[{"src":"brief","b":0,"text":"inherited from our English ancestors, and which had from time immemorial been subject to certain well-recognized exceptions.","cite":"165 U.S. 275, 281"},{"src":"brief","b":1,"text":"from time immemorial been subject to certain well-recognized exceptions arising from the necessities of the case.","cite":"165 U.S. 275, 281"}]},{"t":"case","label":"State v. Hogan","cite":"58 N.E. 572","y":1900,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./58/572/","by":{"0":"26","3":"11"},"q":[{"src":"brief","b":0,"text":"was never intended as a warrant for vicious persons to carry weapons with which to terrorize others.","cite":"58 N.E. 572, 575"}]},{"t":"case","label":"State v. Rhodes","cite":"61 N.C. 453","y":1868,"url":"https://www.courtlistener.com/c/N.C./61/453/","by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"greater evil of raising the curtain upon domestic privacy.","cite":"61 N.C. 453, 459"}]},{"t":"case","label":"State v. Shelby","cite":"2 S.W. 468","y":1886,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./2/468/","by":{"0":"26","3":"11"},"q":[{"src":"brief","b":0,"text":"mischief to be apprehended from an intoxicated person going abroad with fire-arms.","cite":"2 S.W. 468, 469"}]},{"t":"case","label":"Thompson v. Thompson","cite":"218 U.S. 611","y":1910,"id":"scdb/1910-039","sc":1,"by":{"0":"40"}},{"t":"case","label":"United States v. Bena","cite":"664 F.3d 1180","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/664/1180/","by":{"0":"29"}},{"t":"case","label":"United States v. Boyd","cite":"999 F.3d 171","y":2021,"url":"https://www.courtlistener.com/c/F.3d/999/171/","by":{"0":"29","2":"45","3":"17"}},{"t":"case","label":"United States v. Bullock","cite":"2023 WL 4232309","y":2023,"court":"S.D. Miss. June 28","by":{"0":"38","3":"5"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"0":"9, 29"},"q":[{"src":"brief","b":0,"text":"the presence of a firearm increases the likelihood that it will escalate to homicide.","cite":"572 U.S. at 160"}]},{"t":"case","label":"United States v. Daniels","cite":"2023 WL 5091317","y":2023,"court":"5th Cir. Aug. 9","by":{"0":"37"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"by":{"0":"1, 9"},"q":[{"src":"brief","b":0,"text":"Firearms and domestic strife are a potentially deadly combination.","cite":"555 U.S. 415, 427"}]},{"t":"case","label":"United States v. McGinnis","cite":"956 F.3d 747","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/747/","by":{"0":"5","2":"6"}},{"t":"case","label":"United States v. Skoien","cite":"614 F.3d 638","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/638/","by":{"0":"28, 30","2":"32"},"q":[{"src":"brief","b":0,"text":"[t]hat some categorical limits are proper is part of the original meaning","cite":"614 F.3d 638, 640"}]},{"t":"case","label":"Voorhees v. Jackson","cite":"10 Pet. 449","y":1836,"url":"https://www.courtlistener.com/c/Pet./10/449/","by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"There is no principle of law better settled, than that every act of a court of competent jurisdiction shall be presumed to have been rightly done, till the contrary appears.","cite":"10 Pet. 449, 472"}]},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"by":{"0":"44"}},{"t":"case","label":"Zuber v. Allen","cite":"396 U.S. 168","y":1969,"id":"1969/25","sc":1,"by":{"0":"39"}},{"t":"const","label":"Amendment II, Section 5","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 87-342","url":"https://www.govinfo.gov/link/statute/75/757","by":{"0":"26"}},{"t":"law","label":"Bipartisan Safer Communities Act, Pub. L. No. 117-159","url":"https://www.govinfo.gov/link/plaw/117/public/159","by":{"0":"4"}},{"t":"law","label":"Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/452","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1220","by":{"0":"26"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/2014","by":{"0":"27"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(32)","(a)(3)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","2":"10"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)","(g)(3)","(g)(5)(A)","(g)(5)(B)","(g)(8)","(g)(8)(A)","(g)(8)(B)","(g)(8)(C)","(g)(8)(C)(i)","(g)(8)(C)(ii)","(g)(9)","(g)(2)","(g)(4)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"38, 28, 38, 37, 28, 28, 4, 4, 4, 4, 4, 4","1":"2, 21-25","2":"19, 32, 49, 1, 2, 5–12, 17,19, 21, 24, 28, 30–32, 40, 41, 43–50, 4, 45, 11, 45, 46, 49","3":"20, 19, 14, 14, 14, 1, 10, 14-20, 22, 16, 15, 21, 23, 15, 14"},"q":[{"src":"brief","b":0,"text":"engaging in other conduct that would place an intimate partner in reasonable fear of bodily injury to the partner or child.","cite":"18 U.S.C. 922(g)(8)(B)"},{"src":"brief","b":0,"text":"represents a credible threat to the physical safety","cite":"18 U.S.C. 922(g)(8)(C)(i)"},{"src":"brief","b":3,"text":"represents a credible threat to the physical safety","cite":"18 U.S.C. 922(g)(8)(C)(i)"},{"src":"brief","b":3,"text":"the use, attempted use, or threatened use of physical force,","cite":"18 U.S.C. 922(g)(8)(C)(ii)"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"represents a credible threat to the physical safety of [an] intimate partner,","cite":"18 U. S. C. § 922(g)(8)"},{"src":"argument","who":"General Prelogar","text":"Court after court has looked at the government's examples and picked them apart to say: Well, taking them one by one, there's a minute -- minute difference between how this regulation operated in 1791 or the ensuing decades and how Section 922 provisions operate today."}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)(2018)","(a)(8)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 4","2":"11, 11"}},{"t":"case","label":"Page(s) American Legion v. American Humanist Association","cite":"139 S. Ct. 2067","y":2019,"id":"2018/17-1717","sc":1,"by":{"1":"3"}},{"t":"case","label":"Binderup v. Attorney General","cite":"836 F.3d 336","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/836/336/","by":{"1":"14, 16"},"q":[{"src":"brief","b":1,"text":"[d]ebates from the Pennsylvania, Massachusetts and New Hampshire ratifying conventions, which were considered ‘highly influential’ by the Supreme Court in Heller ... confirm that the common law right to keep and bear arms did not extend to those who were likely to commit violent offenses.","cite":"836 F.3d 336, 368"},{"src":"brief","b":1,"text":"the debates from the ratifying conventions point strongly toward a limit on Second Amendment rights centered on dangerousness.","cite":"836 F.3d at 367"}]},{"t":"case","label":"Kennedy v. Bremerton School District","cite":"142 S. Ct. 2407","y":2022,"id":"2021/21-418","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"adorn[ing] the Constitution with rules not supported by its terms and the traditions undergirding them.","cite":"142 S. Ct. 2407, 2428, 2430 n.6"}]},{"t":"case","label":"United States v. Emerson","cite":"270 F.3d 203","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/270/203/","by":{"1":"22","2":"46"},"q":[{"src":"brief","b":1,"text":"not contested or evidence credited by the court reflected a real threat or danger of injury to the protected party by the party enjoined.","cite":"270 F.3d 203, 262"}]},{"t":"case","label":"United States v. Nwoye","cite":"824 F.3d 1129","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/824/1129/","by":{"1":"21, 25"},"q":[{"src":"brief","b":1,"text":"women in battering relationships are often ‘hypervigilant to cues of impending danger and accurately perceive the seriousness of the situation before another person who had not been repeatedly abused might recognize the danger.’","cite":"824 F.3d 1129, 1137"}]},{"t":"const","label":"Amendment II","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"1":"13","2":"1, 6–9, 11, 17–20","3":"1-9"}},{"t":"case","label":"Aptheker v. Sec’y of State","cite":"378 U.S. 500","y":1964,"id":"1963/461","sc":1,"by":{"2":"43"},"q":[{"src":"brief","b":2,"text":"bear a construction rendering it free from constitutional defects.","cite":"378 U.S. 500, 515"}]},{"t":"case","label":"Austin v. United States","cite":"509 U.S. 602","y":1993,"id":"1992/92-6073","sc":1,"by":{"2":"27"},"q":[{"src":"brief","b":2,"text":"took hold in the United States,","cite":"509 U.S. 602, 613"}]},{"t":"case","label":"Boyd v. Palmore","cite":"425 S.W.3d 425","y":2011,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.3d/425/425/","by":{"2":"2"}},{"t":"case","label":"Bradley v. State","cite":"1 Miss. 156","y":1824,"url":"https://www.courtlistener.com/c/Miss./1/156/","by":{"2":"14"}},{"t":"case","label":"Class v. United States","cite":"138 S. Ct. 798","y":2018,"id":"2017/16-424","sc":1,"by":{"2":"7"},"q":[{"src":"brief","b":2,"text":"challenge the Government’s power to criminalize [his] (admitted) conduct.","cite":"138 S. Ct. 798, 804–05"}]},{"t":"case","label":"Dahda v. United States","cite":"138 S. Ct. 1491","y":2018,"id":"2017/17-43","sc":1,"by":{"2":"40"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"by":{"2":"6, 43, 48"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"by":{"2":"42"}},{"t":"case","label":"Edwards v. California","cite":"314 U.S. 160","y":1941,"id":"1940-1955/314us160","sc":1,"by":{"2":"42"}},{"t":"case","label":"Jennings v. State","cite":"5 Tex. App. 298","y":1878,"url":"https://www.courtlistener.com/c/Tex.%20App./5/298/","by":{"2":"28"}},{"t":"case","label":"Luther v. Borden","cite":"48 U.S. 1","y":1849,"id":"1789-1850/48us1","sc":1,"by":{"2":"37"}},{"t":"case","label":"Moore v. Moore-McKinney","cite":"678 S.E.2d 152","y":2009,"court":"Ga. App.","url":"https://www.courtlistener.com/c/S.E.2d/678/152/","by":{"2":"48"}},{"t":"case","label":"Papachristou v. City of Jacksonville","cite":"405 U.S. 156","y":1972,"id":"1971/70-5030","sc":1,"by":{"2":"42"}},{"t":"case","label":"Range v. Att’y Gen.","cite":"69 F.4th 96","y":2023,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/69/96/","by":{"2":"20"}},{"t":"case","label":"Samson v. California","cite":"547 U.S. 843","y":2006,"id":"2005/04-9728","sc":1,"by":{"2":"41, 42"}},{"t":"case","label":"Scarborough v. United States","cite":"431 U.S. 563","y":1977,"id":"1976/75-1344","sc":1,"by":{"2":"40","3":"19"}},{"t":"case","label":"Shapiro v. Thompson","cite":"394 U.S. 618","y":1969,"id":"1967/9","sc":1,"by":{"2":"42"}},{"t":"case","label":"Sprint Commc’ns Co. v. APCC Servs., Inc.","cite":"554 U.S. 269","y":2008,"id":"2007/07-552","sc":1,"by":{"2":"33"}},{"t":"case","label":"Ullman v. United States","cite":"350 U.S. 422","y":1956,"id":"1955/58","sc":1,"by":{"2":"26"}},{"t":"case","label":"United States v. Arledge","cite":"220 F. App’x 864","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/220/864/","by":{"2":"45"}},{"t":"case","label":"United States v. Banks","cite":"339 F.3d 267","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/339/267/","by":{"2":"4, 46"}},{"t":"case","label":"United States v. Bayles","cite":"310 F.3d 1302","y":2002,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/310/1302/","by":{"2":"10"}},{"t":"case","label":"United States v. Brown","cite":"381 U.S. 437","y":1965,"id":"1964/399","sc":1,"by":{"2":"25"},"q":[{"src":"brief","b":2,"text":"doctrine of disqualification, disfranchisement, and banishment by acts of the legislature.","cite":"381 U.S. 437, 444"}]},{"t":"case","label":"United States v. Calor","cite":"340 F.3d 428","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/340/428/","by":{"2":"46"}},{"t":"case","label":"United States v. Knights","cite":"534 U.S. 112","y":2001,"id":"2001/00-1260","sc":1,"by":{"2":"42"}},{"t":"case","label":"United States v. Lippman","cite":"369 F.3d 1039","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/369/1039/","by":{"2":"46"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"by":{"2":"40"},"q":[{"src":"argument","who":"Mr. Wright","text":"Ours is a facial challenge in the way that Lopez was a facial challenge, where the facts of Lopez were clearly within Congress's power under the Commerce Clause."}]},{"t":"case","label":"United States v. Miles","cite":"238 F. Supp. 2d 297","y":2002,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/238/297/","by":{"2":"46"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"by":{"2":"41"},"q":[{"src":"brief","b":2,"text":"no better example of the police power, which the Founders denied the National Government and reposed in the States, than the suppression of violent crime and vindication of its victims.","cite":"529 U.S. 598, 618"}]},{"t":"case","label":"United States v. N.Y. Tel. Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"by":{"2":"40"}},{"t":"case","label":"United States v. Penn","cite":"969 F.3d 450","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/969/450/","by":{"2":"11"},"q":[{"src":"argument","who":"Mr. Wright","text":"In response to Justice Gorsuch's question about how the courts of appeals handle the issue of self-defense, necessity, duress, we cite a case on page 11 of our brief, United States versus Penn, I remember that case very well, it will show you how they handle it."}]},{"t":"case","label":"United States v. Sanchez","cite":"639 F.3d 1201","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/639/1201/","by":{"2":"11"}},{"t":"case","label":"United States v. Seekins","cite":"52 F.4th 988","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/52/988/","by":{"2":"40"}},{"t":"case","label":"United States v. Vaello Madero","cite":"142 S. Ct. 1539","y":2022,"id":"2021/20-303","sc":1,"by":{"2":"21"}},{"t":"case","label":"United States v. Waddell","cite":"112 U.S. 76","y":1884,"id":"scdb/1884-012","sc":1,"by":{"2":"26"}},{"t":"case","label":"United States v. Wilkey","cite":"2020 WL 4464668","y":2020,"court":"D. Mont. Aug. 4","by":{"2":"10, 46"}},{"t":"case","label":"United States v. Wilson","cite":"159 F.3d 280","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/280/","by":{"2":"46"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"9, 42"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"2":"9"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"25, 26, 42"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"42","3":"8"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"2":"42","3":"20"}},{"t":"const","label":"Article I, Section 8","by":{"2":"40"}},{"t":"const","label":"Article I, Section 9","clauses":[["habeas","Suspension Clause (Habeas Corpus)"],["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"],["appropriations","Appropriations Clause"],["emoluments","Emoluments Clauses"]],"by":{"2":"25, 36"}},{"t":"const","label":"Article I, Section 10","clauses":[["contract-clause","Contract Clause"],["compact","Compact Clause"]],"text":"No State shall enter into any Treaty, Alliance, or Confederation; grant Letters of Marque and Reprisal; coin Money; emit Bills of Credit; make any Thing but gold and silver Coin a Tender in Payment of Debts; pass any Bill of Attainder, ex post facto Law, or Law impairing the Obligation of Contracts, or grant any Title of Nobility. No State shall, without the Consent of the Congress, lay any Imposts or Duties on Imports or Exports, except what may be absolutely necessary for executing it's inspection Laws: and the net Produce of all Duties and Imposts, laid by any State on Imports or Exports, shall be for the Use of the Treasury of the United States; and all such Laws shall be subject to the Revision and Controul of the Congress. No State shall, without the Consent of Congress, lay any Duty of Tonnage, keep Troops, or Ships of War in time of Peace, enter into any Agreement or Compact with another State, or with a foreign Power, or engage in War, unless actually invaded, or in such imminent Danger as will not admit of delay.","by":{"2":"25"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"2":"25"}},{"t":"const","label":"Article III, Section 3","clauses":[["treason","Treason Clause"]],"text":"Treason against the United States, shall consist only in levying War against them, or in adhering to their Enemies, giving them Aid and Comfort. No Person shall be convicted of Treason unless on the Testimony of two Witnesses to the same overt Act, or on Confession in open Court. The Congress shall have Power to declare the Punishment of Treason, but no Attainder of Treason shall work Corruption of Blood, or Forfeiture except during the Life of the Person attainted.","by":{"2":"25"}},{"t":"usc","label":"18 U.S.C. § 925","url":"https://www.law.cornell.edu/uscode/text/18/925","subs":["(a)","(a)(1)"],"stext":{"head":"§925. Exceptions: Relief from disabilities","paras":[[0,"(a)(1) The provisions of this chapter, except for sections 922(d)(9) and 922(g)(9) and provisions relating to firearms subject to the prohibitions of section 922(p), shall not apply with respect to the transportation, shipment, receipt, possession, or importation of any firearm or ammunition imported for, sold or shipped to, or issued for the use of, the United States or any department or agency thereof or any State or any department, agency, or political subdivision thereof."],[0,"(2) The provisions of this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), shall not apply with respect to (A) the shipment or receipt of firearms or ammunition when sold or issued by the Secretary of the Army pursuant to section 4308 of title 10 before the repeal of such section by section 1624(a) of the Corporation for the Promotion of Rifle Practice and Firearms Safety Act, and (B) the transportation of any such firearm or ammunition carried out to enable a person, who lawfully received such firearm or ammunition from the Secretary of the Army, to engage in military training or in competitions."],[0,"(3) Unless otherwise prohibited by this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), or any other Federal law, a licensed importer, licensed manufacturer, or licensed dealer may ship to a member of the United States Armed Forces on active duty outside the United States or to clubs, recognized by the Department of Defense, whose entire membership is composed of such members, and such members or clubs may receive a firearm or ammunition determined by the Attorney General to be generally recognized as particularly suitable for sporting purposes and intended for the personal use of such member or club."],[0,"(4) When established to the satisfaction of the Attorney General to be consistent with the provisions of this chapter, except for provisions relating to firearms subject to the prohibitions of section 922(p), and other applicable Federal and State laws and published ordinances, the Attorney General may authorize the transportation, shipment, receipt, or importation into the United States to the place of residence of any member of the United States Armed Forces who is on active duty outside the United States (or who has been on active duty outside the United States within the sixty day period immediately preceding the transportation, shipment, receipt, or importation), of any firearm or ammunition which is (A) determined by the Attorney General to be generally recognized as particularly suitable for sporting purposes, or determined by the Department of Defense to be a type of firearm normally classified as a war souvenir, and (B) intended for the personal use of such member."],[0,"(5) For the purpose of paragraph (3) of this subsection, the term \"United States\" means each of the several States and the District of Columbia."],[0,"(b) A licensed importer, licensed manufacturer, licensed dealer, or licensed collector who is indicted for a crime punishable by imprisonment for a term exceeding one year, may, notwithstanding any other provision of this chapter, continue operation pursuant to his existing license (if prior to the expiration of the term of the existing license timely application is made for a new license) during the term of such indictment and until any conviction pursuant to the indictment becomes final."],[0,"(c) A person who is prohibited from possessing, shipping, transporting, or receiving firearms or ammunition may make application to the Attorney General for relief from the disabilities imposed by Federal laws with respect to the acquisition, receipt, transfer, shipment, transportation, or possession of firearms, and the Attorney General may grant such relief if it is established to his satisfaction that the circumstances regarding the disability, and the applicant's record and reputation, are such that the applicant will not be likely to act in a manner dangerous to public safety and that the granting of the relief would not be contrary to the public interest. Any person whose application for relief from disabilities is denied by the Attorney General may file a petition with the United States district court for the district in which he resides for a judicial review of such denial. The court may in its discretion admit additional evidence where failure to do so would result in a miscarriage of justice. A licensed importer, licensed manufacturer, licensed dealer, or licensed collector conducting operations under this chapter, who makes application for relief from the disabilities incurred under this chapter, shall not be barred by such disability from further operations under his license pending final action on an application for relief filed pursuant to this section. Whenever the Attorney General grants relief to any person pursuant to this section he shall promptly publish in the Federal Register notice of such action, together with the reasons therefor."],[0,"(d) The Attorney General shall authorize a firearm or ammunition to be imported or brought into the United States or any possession thereof if the firearm or ammunition—"],[1,"(1) is being imported or brought in for scientific or research purposes, or is for use in connection with competition or training pursuant to chapter 751 of title 10;"],[1,"(2) is an unserviceable firearm, other than a machinegun as defined in section 5845(b) of the Internal Revenue Code of 1986 (not readily restorable to firing condition), imported or brought in as a curio or museum piece;"],[1,"(3) is of a type that does not fall within the definition of a firearm as defined in section 5845(a) of the Internal Revenue Code of 1986 and is generally recognized as particularly suitable for or readily adaptable to sporting purposes, excluding surplus military firearms, except in any case where the Attorney General has not authorized the importation of the firearm pursuant to this paragraph, it shall be unlawful to import any frame, receiver, or barrel of such firearm which would be prohibited if assembled; or"],[1,"(4) was previously taken out of the United States or a possession by the person who is bringing in the firearm or ammunition."],[0,"The Attorney General shall permit the conditional importation or bringing in of a firearm or ammunition for examination and testing in connection with the making of a determination as to whether the importation or bringing in of such firearm or ammunition will be allowed under this subsection."],[0,"(e) Notwithstanding any other provision of this title, the Attorney General shall authorize the importation of, by any licensed importer, the following:"],[1,"(1) All rifles and shotguns listed as curios or relics by the Attorney General pursuant to section 921(a)(13), and"],[1,"(2) All handguns, listed as curios or relics by the Attorney General pursuant to section 921(a)(13), provided that such handguns are generally recognized as particularly suitable for or readily adaptable to sporting purposes."],[0,"(f) The Attorney General shall not authorize, under subsection (d), the importation of any firearm the importation of which is prohibited by section 922(p)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/925?type=usc&year=mostrecent&link-type=html"},"by":{"2":"10, 49","3":"20"}},{"t":"usc","label":"18 U.S.C. § 3571","url":"https://www.law.cornell.edu/uscode/text/18/3571","subs":["(b)(3)"],"by":{"2":"11"}},{"t":"case","label":"Adoptive Couple v. Baby Girl","cite":"570 U.S. 637","y":2013,"id":"2012/12-399","sc":1,"by":{"3":"8"}},{"t":"case","label":"Christian Legal Society v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"by":{"3":"22"}},{"t":"case","label":"Cox v. New Hampshire","cite":"312 U.S. 569","y":1941,"id":"1940-1955/312us569","sc":1,"by":{"3":"22"},"q":[{"src":"brief","b":3,"text":"Civil liberties, as guaranteed by the Constitution, imply the existence of an organized society maintaining public order.","cite":"312 U.S. 569, 574"}]},{"t":"case","label":"Hurtado v. California","cite":"110 U.S. 516","y":1884,"id":"1850-1900/110us516","sc":1,"by":{"3":"4"},"q":[{"src":"brief","b":3,"text":"[T]o hold that such a characteristic is essential * * * would be to deny every quality of the law but its age, and to render it incapable of progress or improvement.","cite":"110 U.S. 516, 529"}]},{"t":"case","label":"Mullane v. Central Hanover Bank & Trust Co.","cite":"339 U.S. 306","y":1950,"id":"scdb/1949-066","sc":1,"by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"that deprivation of life, liberty or property by adjudication be preceded by notice and opportunity for hearing.","cite":"339 U.S. 306, 313"}]},{"t":"case","label":"Nunn v. State","cite":"1 Ga. 243","y":1846,"url":"https://www.courtlistener.com/c/Ga./1/243/","by":{"3":"21"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"by":{"3":"8, 19"},"q":[{"src":"brief","b":3,"text":"the idea that a single right can mean two different things depending on whether it is being invoked against the federal or a state government.","cite":"140 S. Ct. at 1398"}]},{"t":"case","label":"State v. Morales","cite":"869 S.W.2d 941","y":1994,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/869/941/","by":{"3":"15"}},{"t":"case","label":"United States v. Connelly","cite":"2023 WL 2806324","y":2023,"court":"W.D. Tex. Apr. 6","by":{"3":"5"}},{"t":"case","label":"United States v. Harper","cite":"2023 WL 5672311","y":2023,"court":"M.D. Pa. Sept. 1","by":{"3":"5"}},{"t":"case","label":"United States v. Quailes","cite":"2023 WL 5401733","y":2023,"court":"M.D. Pa. Aug. 22","by":{"3":"5"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"the challenger must establish that no set of circumstances exists under which the Act would be valid.","cite":"481 U.S. 739, 745"},{"src":"opinion","who":"Justice Gorsuch, concurring","text":"most diffcult challenge to mount successfully","cite":"481 U. S. 739, 745"},{"src":"argument","who":"Mr. Wright","text":"It typically comes up in the civil context where someone is suing to enjoin the enforcement of a statute and -- and so the Salerno test it's called, you know, comes into play as to, typically, that assumes there is a valid application or a space of valid application of the statute, and then the complaint is either there's too much outside or my case is outside or something like that."}]},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"3":"19"}},{"t":"const","label":"Amendment XIX","clauses":[["nineteenth-amendment","Nineteenth Amendment"]],"text":"The right of citizens of the United States to vote shall not be denied or abridged by the United States or by any State on account of sex. Congress shall have power to enforce this article by appropriate legislation.","by":{"3":"12"}},{"t":"usc","label":"18 U.S.C. § 928","url":"https://www.law.cornell.edu/uscode/text/18/928","stext":{"head":"§928. Separability","paras":[[0,"If any provision of this chapter or the application thereof to any person or circumstance is held invalid, the remainder of the chapter and the application of such provision to other persons not similarly situated or to other circumstances shall not be affected thereby."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/928?type=usc&year=mostrecent&link-type=html"},"by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"the application of such provision to other persons not similarly situated or to other circumstances.","cite":"18 U.S.C. 928"}]},{"t":"usc","label":"34 U.S.C. § 40901","url":"https://www.law.cornell.edu/uscode/text/34/40901","by":{"3":"21"}},{"t":"usc","label":"34 U.S.C. § 40903","url":"https://www.law.cornell.edu/uscode/text/34/40903","subs":["(1)"],"by":{"3":"21"}},{"t":"usc","label":"34 U.S.C. § 40911","url":"https://www.law.cornell.edu/uscode/text/34/40911","subs":["(b)(3)(C)(i)"],"by":{"3":"21"}},{"t":"usc","label":"34 U.S.C. § 40913","url":"https://www.law.cornell.edu/uscode/text/34/40913","subs":["(b)(5)"],"by":{"3":"21"}},{"t":"usc","label":"34 U.S.C. § 40941","url":"https://www.law.cornell.edu/uscode/text/34/40941","subs":["(a)"],"by":{"3":"21"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"3":"19"}}]};